-- TRYNKA ONLINE — виконати один раз у Supabase SQL Editor
create table profiles(id uuid primary key references auth.users(id) on delete cascade,nickname text unique not null,created_at timestamptz default now());
create table rooms(id bigint generated by default as identity primary key,owner_id uuid references profiles(id) on delete cascade,name text not null,max_players int not null check(max_players between 2 and 8),turn_seconds int not null default 30,ante int not null default 10,created_at timestamptz default now());
create table room_players(room_id bigint references rooms(id) on delete cascade,user_id uuid references profiles(id) on delete cascade,joined_at timestamptz default now(),primary key(room_id,user_id));
create table messages(id bigint generated by default as identity primary key,room_id bigint references rooms(id) on delete cascade,user_id uuid references profiles(id) on delete cascade,body text not null check(char_length(body)<=100),created_at timestamptz default now());
create table friends(user_id uuid references profiles(id) on delete cascade,friend_id uuid references profiles(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,friend_id));
create table invites(id bigint generated by default as identity primary key,room_id bigint references rooms(id) on delete cascade,from_user uuid references profiles(id) on delete cascade,to_user uuid references profiles(id) on delete cascade,status text default 'pending',created_at timestamptz default now());

alter table profiles enable row level security; alter table rooms enable row level security; alter table room_players enable row level security; alter table messages enable row level security; alter table friends enable row level security; alter table invites enable row level security;
create policy "profiles read" on profiles for select to authenticated using(true); create policy "profile own write" on profiles for all to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "rooms read" on rooms for select to authenticated using(true); create policy "rooms insert" on rooms for insert to authenticated with check(auth.uid()=owner_id); create policy "rooms delete owner" on rooms for delete to authenticated using(auth.uid()=owner_id);
create policy "players read" on room_players for select to authenticated using(true); create policy "players join" on room_players for insert to authenticated with check(auth.uid()=user_id); create policy "players leave" on room_players for delete to authenticated using(auth.uid()=user_id);
create policy "messages read" on messages for select to authenticated using(true); create policy "messages send" on messages for insert to authenticated with check(auth.uid()=user_id);
create policy "friends own" on friends for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "invites read" on invites for select to authenticated using(auth.uid()=to_user or auth.uid()=from_user); create policy "invites send" on invites for insert to authenticated with check(auth.uid()=from_user); create policy "invites update" on invites for update to authenticated using(auth.uid()=to_user);
alter publication supabase_realtime add table rooms,room_players,messages,invites;
